/**
 * Cross-language parity test: the TypeScript port must reproduce the Python
 * reference outputs stored in data/parity.json (generated by
 * `python3 -m experiments.export_web`). Run with `npm run parity`.
 */
import { readFileSync } from "node:fs";
import {
  ArcTanhLime, DeltaAnchorEnsemble, LimeTabular, mlpPredictor, ONE_D_FUNCTIONS, Rng,
} from "../lib/core/index.ts";
import type { ArcTanhConfig, ArcTanhResult, Bounds, LimeResult, MlpWeights, OneDName } from "../lib/core/index.ts";

const fx = JSON.parse(readFileSync(new URL("../data/parity.json", import.meta.url), "utf8"));
const moonsModel: MlpWeights = JSON.parse(readFileSync(new URL("../data/moons.json", import.meta.url), "utf8")).model;

const REL = 1e-9;
const ABS = 1e-12;
let checks = 0;
let worst = 0;
let worstAbs = 0;
const failures: string[] = [];

function num(name: string, got: number | null, want: number | null): void {
  checks++;
  if (got === null || want === null) {
    if (got !== want) failures.push(`${name}: got ${got}, want ${want}`);
    return;
  }
  const err = Math.abs(got - want);
  worstAbs = Math.max(worstAbs, err);
  const rel = err / Math.max(Math.abs(want), 1e-300);
  if (err > ABS) worst = Math.max(worst, rel);
  if (err > ABS && rel > REL) failures.push(`${name}: got ${got}, want ${want} (rel ${rel.toExponential(2)})`);
}

function arr(name: string, got: number[] | null, want: number[] | null): void {
  if (got === null || want === null) return num(name, got as null, want as null);
  if (got.length !== want.length) {
    failures.push(`${name}: length ${got.length} vs ${want.length}`);
    return;
  }
  got.forEach((g, i) => num(`${name}[${i}]`, g, want[i]));
}

function same(name: string, got: unknown, want: unknown): void {
  checks++;
  if (got !== want) failures.push(`${name}: got ${String(got)}, want ${String(want)}`);
}

function checkLime(name: string, res: LimeResult, want: any, probes: number[][]): void {
  num(`${name}.intercept`, res.surrogate.intercept, want.intercept);
  arr(`${name}.coef`, res.surrogate.coef, want.coef);
  num(`${name}.score`, res.score, want.score);
  arr(`${name}.pred`, probes.map((p) => res.surrogate.predict(p)), want.predictions);
}

function checkArcTanh(name: string, res: ArcTanhResult, want: any, probes: number[][]): void {
  for (const key of ["raw_lo", "raw_hi", "lo", "hi", "score", "clipped_fraction"] as const) {
    const got = { raw_lo: res.rawLo, raw_hi: res.rawHi, lo: res.lo, hi: res.hi, score: res.score,
      clipped_fraction: res.clippedFraction }[key];
    num(`${name}.${key}`, got, want[key]);
  }
  same(`${name}.fallback`, res.fallback, want.fallback);
  same(`${name}.n_queries`, res.nQueries, want.n_queries);
  const s = res.surrogate;
  const link = res.linkSurrogate;
  num(`${name}.beta0`, "beta0" in s ? s.beta0 : null, want.beta0);
  arr(`${name}.beta`, "beta" in s ? s.beta : null, want.beta);
  num(`${name}.link_beta0`, "beta0" in link ? link.beta0 : null, want.link_beta0);
  arr(`${name}.link_beta`, "beta" in link ? link.beta : null, want.link_beta);
  for (const [side, walk] of [["walk_up", res.walkUp], ["walk_down", res.walkDown]] as const) {
    const w = want[side];
    if (w === null) {
      same(`${name}.${side}`, walk, null);
      continue;
    }
    same(`${name}.${side}.steps`, walk!.points.length - 1, w.steps);
    same(`${name}.${side}.stop_reason`, walk!.stopReason, w.stop_reason);
    num(`${name}.${side}.end_value`, walk!.values[walk!.values.length - 1], w.end_value);
  }
  arr(`${name}.attribution`, res.attribution, want.attribution);
  arr(`${name}.pred`, probes.map((p) => s.predict(p)), want.predictions);
}

const camel: Record<string, keyof ArcTanhConfig> = {
  fit: "fit", pin_origin: "pinOrigin", asymptotes: "asymptotes", margin: "margin", epsilon: "epsilon",
  max_steps: "maxSteps",
};

// 1. random streams
const r1 = new Rng(123);
arr("rng.uniform", fx.uniform_seed123.map(() => r1.uniform()), fx.uniform_seed123);
const r2 = new Rng(7);
arr("rng.normal", fx.normal_seed7.map(() => r2.normal()), fx.normal_seed7);
num("rng.spawn", new Rng(99).spawn(3).uniform(), fx.spawn_99_3);

// 2. 1-D curves
const bounds1d = fx.one_d.bounds as Bounds;
for (const c of fx.one_d.cases) {
  const g = ONE_D_FUNCTIONS[c.function as OneDName];
  const f = (x: number[]) => g(x[0]);
  const name = `${c.function}@${c.x0[0]}`;
  checkLime(`${name}.lime`, new LimeTabular([1], { numSamples: c.num_samples }).explain(f, c.x0, new Rng(c.seed)),
    c.lime, fx.one_d.probes);
  checkArcTanh(`${name}.arctanh`,
    new ArcTanhLime([1], { numSamples: c.num_samples }, bounds1d).explain(f, c.x0, new Rng(c.seed)),
    c.arctanh, fx.one_d.probes);
}

// 3. configuration variants
const sine = (x: number[]) => Math.sin(x[0]);
for (const [key, v] of Object.entries<any>(fx.variants)) {
  const cfg: Partial<ArcTanhConfig> = { numSamples: 250 };
  for (const [k, val] of Object.entries(v.config)) (cfg as any)[camel[k]] = val;
  checkArcTanh(`variant.${key}`, new ArcTanhLime([1], cfg, bounds1d).explain(sine, [0.7], new Rng(5)), v.result,
    fx.one_d.probes);
}

// 4. ensembles
const ens = new DeltaAnchorEnsemble(new ArcTanhLime([1], { numSamples: 200 }, bounds1d), { delta: 1 }, bounds1d)
  .explain(sine, [0.7], new Rng(5));
arr("ensemble.anchors", ens.anchors.flat(), fx.ensembles.arctanh.anchors.flat());
same("ensemble.n_queries", ens.nQueries, fx.ensembles.arctanh.n_queries);
arr("ensemble.pred", fx.one_d.probes.map((p: number[]) => ens.surrogate.predict(p)), fx.ensembles.arctanh.predictions);
arr("ensemble.grad", [[0.2], [1.3], [2.9]].flatMap((p) => ens.surrogate.gradient(p)),
  fx.ensembles.arctanh.blend_gradient.flat());
const lens = new DeltaAnchorEnsemble(new LimeTabular([1], { numSamples: 200 }), { delta: 1.5, rings: 2 }, bounds1d)
  .explain(sine, [0.7], new Rng(6));
arr("lime_ensemble.anchors", lens.anchors.flat(), fx.ensembles.lime_rings2.anchors.flat());
arr("lime_ensemble.pred", fx.one_d.probes.map((p: number[]) => lens.surrogate.predict(p)),
  fx.ensembles.lime_rings2.predictions);

// 5. two-moons MLP
const net = mlpPredictor(moonsModel);
arr("moons.mlp", fx.moons.probes.map((p: number[]) => net(p)), fx.moons.mlp_outputs);
for (const [i, c] of fx.moons.cases.entries()) {
  checkLime(`moons${i}.lime`, new LimeTabular(fx.moons.scale, { numSamples: c.num_samples })
    .explain(net, c.x0, new Rng(c.seed)), c.lime, fx.moons.probes);
  checkArcTanh(`moons${i}.arctanh`, new ArcTanhLime(fx.moons.scale, { numSamples: c.num_samples }, fx.moons.bounds)
    .explain(net, c.x0, new Rng(c.seed)), c.arctanh, fx.moons.probes);
}

console.log(`${checks} checks, worst absolute deviation ${worstAbs.toExponential(2)}, worst relative ${worst.toExponential(2)} (tolerance ${REL})`);
if (failures.length) {
  console.error(`${failures.length} FAILED:\n  ` + failures.slice(0, 30).join("\n  "));
  process.exit(1);
}
console.log("parity OK: the TypeScript port reproduces the Python reference");
